query:
SELECT ?item ?prop ?st ?rank ?value ?at ?atPrec ?atCal ?start ?startPrec ?startCal ?end ?endPrec ?endCal ?nature WHERE {
  VALUES ?item { wd:Q2577303 wd:Q172579 wd:Q38 wd:Q180393 wd:Q170174 wd:Q154849 wd:Q223936 wd:Q153660 }
  VALUES (?prop ?p ?ps ?psv) { ("P571" p:P571 ps:P571 psv:P571) ("P576" p:P576 ps:P576 psv:P576) ("P36" p:P36 ps:P36 psv:P36) ("P122" p:P122 ps:P122 psv:P122) ("P1448" p:P1448 ps:P1448 psv:P1448) ("P41" p:P41 ps:P41 psv:P41) ("P35" p:P35 ps:P35 psv:P35) ("P6" p:P6 ps:P6 psv:P6) ("P1906" p:P1906 ps:P1906 psv:P1906) ("P1313" p:P1313 ps:P1313 psv:P1313) }
  ?item ?p ?st . ?st wikibase:rank ?rank ; ?ps ?value .
  FILTER(?rank != wikibase:DeprecatedRank)
  OPTIONAL { ?st ?psv [ wikibase:timeValue ?at ; wikibase:timePrecision ?atPrec ; wikibase:timeCalendarModel ?atCal ] . }
  OPTIONAL { ?st pqv:P580 [ wikibase:timeValue ?start ; wikibase:timePrecision ?startPrec ; wikibase:timeCalendarModel ?startCal ] . }
  OPTIONAL { ?st pqv:P582 [ wikibase:timeValue ?end ; wikibase:timePrecision ?endPrec ; wikibase:timeCalendarModel ?endCal ] . }
  OPTIONAL { ?st pq:P5102 ?nature . }
}
